<?php

function common_characters($string1, $string2) {
    // convert the strings to arrays of characters
    $string1_chars = str_split($string1);
    $string2_chars = str_split($string2);

    // count the number of characters in common using array_intersect
    $common_chars = array_intersect($string1_chars, $string2_chars);
    $count = count($common_chars);

    return $count;
}

// test the function
$string1 = "hello world";
$string2 = "goodbye world";
echo common_characters($string1, $string2); // outputs 7 which is the number of characters common in the two strings

